<script lang="ts">
  import { pokePelago } from '../stores/pokePelago.svelte.ts';
  import type { PokePelagoIslandId } from '../lib/pokePelagoLogic.ts';
  import { game } from '../../gameManager.ts';
  import PokePelagoAssignPicker from './PokePelagoAssignPicker.svelte';

  let snap = $derived(pokePelago.snapshot);
  let ui = $derived(snap.ui);
  let claimToast = $state<string | null>(null);
  let claimToastTimer: ReturnType<typeof setTimeout> | null = null;

  function showClaimToast(): void {
    claimToast = ui.claimToast;
    if (claimToastTimer) clearTimeout(claimToastTimer);
    claimToastTimer = setTimeout(() => {
      claimToast = null;
      claimToastTimer = null;
    }, 1600);
  }

  function levelAbbrev(level: number | null): string {
    if (level == null) return '';
    const tpl = ui.levelAbbrev || 'Lv.{level}';
    if (tpl.includes('{level}')) return tpl.replaceAll('{level}', String(level));
    const trimmed = tpl.replace(/\s+$/, '');
    return `${trimmed}${level}`;
  }

  function claim(islandId: PokePelagoIslandId): void {
    const ok = game?.claimPokePelagoIsland?.(islandId);
    if (ok) showClaimToast();
  }

  function unassign(islandId: PokePelagoIslandId): void {
    game?.assignPokePelago?.(islandId, null, 'storage', 0);
  }

  function claimAll(): void {
    const ok = game?.claimAllPokePelago?.();
    if (ok) showClaimToast();
  }
</script>

<div class="poke-pelago-modal-inner">
  <p class="poke-pelago-intro">{ui.intro}</p>
  <p class="poke-pelago-cap-hint">{ui.offlineCapHint}</p>

  <div class="poke-pelago-level-row" role="status">
    <strong>{snap.levelLabel}</strong>
    <span class="poke-pelago-level-bonus">{snap.levelBonusLabel}</span>
    {#if snap.levelProgressLabel}
      <span class="poke-pelago-level-progress">{snap.levelProgressLabel}</span>
    {/if}
  </div>

  {#if claimToast}
    <div class="poke-pelago-claim-toast" role="status" aria-live="polite">{claimToast}</div>
  {/if}

  {#if snap.evelupBanner}
    <div class="poke-pelago-evelup-banner" role="status">{snap.evelupBanner}</div>
  {/if}

  {#if snap.claimableCount > 0}
    <div class="poke-pelago-toolbar">
      <button type="button" class="miltank-farm-btn miltank-farm-btn--claim poke-pelago-claim-all" onclick={claimAll}>
        {ui.claimAll}
      </button>
    </div>
  {/if}

  {#each snap.islands as island (island.id)}
    <div
      class="poke-pelago-island"
      class:poke-pelago-island--locked={!island.unlocked}
      class:poke-pelago-island--claimable={island.claimable}
    >
      <div class="poke-pelago-island-head">
        <h3>{island.name}</h3>
        <span class="poke-pelago-role">{island.role}</span>
      </div>

      {#if !island.unlocked}
        <p class="poke-pelago-locked">{island.unlockHint ?? ui.lockedGeneric}</p>
      {:else}
        <div class="poke-pelago-island-body">
          <div class="poke-pelago-island-col poke-pelago-island-col--meta">
            <div class="poke-pelago-assignee">
              {#if island.assignedUid && island.assignedSpriteUrl}
                <img
                  class="poke-pelago-assignee-sprite"
                  src={island.assignedSpriteUrl}
                  alt=""
                  width="48"
                  height="48"
                />
                <div class="poke-pelago-assignee-meta">
                  <strong>{island.assignedName}</strong>
                  <span>
                    {levelAbbrev(island.assignedLevel)}
                    {#if island.assigneeBonusLabel}
                      <span class="poke-pelago-assignee-bonus"> · {island.assigneeBonusLabel}</span>
                    {/if}
                  </span>
                </div>
              {:else}
                <div class="poke-pelago-assignee-empty">{ui.unassigned}</div>
              {/if}
            </div>

            <div class="poke-pelago-products">
              <span class="poke-pelago-products-title">{ui.productsTitle}</span>
              <ul class="poke-pelago-products-list">
                {#each island.products as product (product)}
                  <li>{product}</li>
                {/each}
              </ul>
            </div>

            {#if island.rateLabel}
              <p class="poke-pelago-rate">{island.rateLabel}</p>
            {/if}
            {#if island.offlineHint}
              <p class="poke-pelago-offline">{island.offlineHint}</p>
            {/if}
            {#if island.poolHint}
              <p class="poke-pelago-pool" title={island.poolHint}>{island.poolHint}</p>
            {/if}
            {#if island.pityLabel}
              <p class="poke-pelago-pity">{island.pityLabel}</p>
            {/if}
          </div>

          <div class="poke-pelago-island-col poke-pelago-island-col--progress">
            {#if island.progressRows.length > 0}
              <div class="poke-pelago-progress-rows">
                {#each island.progressRows as row (row.id)}
                  <div class="poke-pelago-progress-row">
                    <span class="poke-pelago-progress-row-label">{row.label}</span>
                    <span
                      class="ultimate-slot-pick-tooltip-bar poke-pelago-progress-bar"
                      role="progressbar"
                      aria-valuemin={0}
                      aria-valuemax={100}
                      aria-valuenow={Math.round(row.fill * 100)}
                      aria-label={row.label}
                    >
                      <span
                        class="ultimate-slot-pick-tooltip-bar-fill"
                        class:poke-pelago-progress-fill--beans={row.id === 'beans'}
                        class:poke-pelago-progress-fill--prestige={row.id === 'prestige'}
                        style={`width: ${Math.round(row.fill * 100)}%`}
                      ></span>
                    </span>
                  </div>
                {/each}
              </div>
            {:else if island.progressLabel}
              <p class="poke-pelago-progress">{island.progressLabel}</p>
            {/if}
            {#if island.etaLabel}
              <p class="poke-pelago-eta" class:poke-pelago-eta--ready={island.claimable}>{island.etaLabel}</p>
            {/if}

            {#if island.pendingLabel}
              <p class="poke-pelago-pending" class:poke-pelago-pending--ready={island.claimable}>
                {island.pendingLabel}
              </p>
            {/if}
            {#if island.pendingItems.length > 0}
              <ul class="poke-pelago-item-list">
                {#each island.pendingItems as item (item.itemKey)}
                  <li class="poke-pelago-item-row">
                    {#if item.iconUrl}
                      <img
                        class="poke-pelago-item-icon item-sprite-img"
                        src={item.iconUrl}
                        alt=""
                        width="24"
                        height="24"
                      />
                    {/if}
                    <span>{item.name} ×{item.qty}</span>
                  </li>
                {/each}
              </ul>
            {/if}
          </div>
        </div>

        <div class="poke-pelago-actions">
          <PokePelagoAssignPicker
            islandId={island.id}
            islandName={island.name}
            candidates={snap.candidates}
            {ui}
            label={ui.assign}
          />
          {#if island.assignedUid}
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--reroll"
              onclick={() => unassign(island.id)}
            >
              {ui.unassign}
            </button>
          {/if}
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--claim"
            disabled={!island.claimable}
            onclick={() => claim(island.id)}
          >
            {ui.claim}
          </button>
        </div>
      {/if}
    </div>
  {/each}
</div>

